import numpy as np
# invalid input: a placement fraction of 0.5 puts both particles of a cell on the same point and must raise ValueError
def _catches_value_error(fn):
    try:
        fn()
    except ValueError:
        return np.array([1.0])
    return np.array([0.0])
assert np.allclose(_catches_value_error(lambda: fmpm_bar_operator(8.0, 1.0, 0.5, 2.0, 0.5, 0.5, 'FMPM', 4, 1.0, 1)), target)

